/// Constructs a row of length `n` where the element at index `i` is `i` (as `u8`).
/// For example, create_row(5) -> [0, 1, 2, 3, 4].
fn create_row(n: u8) -> Vec<u8> {
    // Allocate exactly n elements up front to avoid reallocations.
    let mut row = Vec::with_capacity(n as usize);
    for i in 0..(n as usize) {
        row.push(i as u8);
    }
    row
}

/// Returns a two-dimensional grid containing exactly one row,
/// which is the row produced by `create_row(n)`.
/// For n = 0, this yields `vec![vec![]]`.
fn indices(n: u8) -> Vec<Vec<u8>> {
    vec![create_row(n)]
}

fn main() {
    // Example usage and simple tests
    assert_eq!(create_row(0), Vec::<u8>::new());
    assert_eq!(create_row(5), vec![0, 1, 2, 3, 4]);

    assert_eq!(indices(0), vec![vec![]]);
    assert_eq!(indices(5), vec![vec![0, 1, 2, 3, 4]]);

    println!("All tests passed!");
}